//
// The transform, off the audio thread and off the UI thread.
//
// WHY A WORKER AT ALL. A real-4096 transform plus the dB stage is a few hundred
// microseconds, which sounds affordable on the main thread until it lands in
// the same 20 ms slot as layout, a canvas paint and whatever else the page is
// doing; the spectrogram then stutters exactly when the singer is loudest,
// because that is when everything else is busiest too. The audio thread cannot
// host it either — `pcm-hop.worklet.ts` explains why. So capture is real-time,
// rendering is display-rate, and the arithmetic between them is here.
//
// IT CALLS `spectrumFrame`, AND NOTHING ELSE COMPUTES A SPECTRUM. That function
// is the one the golden suite measures against the Python oracle
// (`tests/golden/spectrum-oracle.test.ts`, max residual 1.85e-5 dB over the
// nineteen Tier-0 spectra, against a 0.01 dB row). A second "fast" path here
// would be a second convention, and ADR 0021 decision 2 exists to stop exactly
// that: "the thing measured against the goldens at W1 is literally the thing
// the AudioWorklet feeds at 50 Hz".
//
// SMOOTHING AND HOLD ARE IN LINEAR POWER. ADR 0006 D8, and the reason is a
// number: the log-domain mean of a noise-like bin is `−γ·10/ln 10` = −2.507 dB
// low. `SpectrumFrame.linear` is exposed by the pipeline precisely so that this
// file can accumulate there and convert afterwards, and the direction of the
// coefficient is ADR 0021 decision 7(d)'s — `s` is the weight of the PREVIOUS
// frame, so a larger value is smoother.
//
// ---------------------------------------------------------------------------
// ONE KNOWN APPROXIMATION, STATED RATHER THAN HIDDEN — the DC blocker across
// overlapping windows.
//
// ADR 0006 D7 defines the blocker on the STREAM: `y[n] = x[n] − x[n−1] +
// R·y[n−1]`, one state pair, before the window. What arrives here is not a
// stream but the newest `window_length_samples` every `hop_samples`, so
// consecutive windows OVERLAP (6.4× at the live-singing preset). The W1
// contract pins this Worker to "keep the DcBlocker across hops", which is what
// the code does — one instance, state carried, `reset()` only on a stream
// change. The consequence is precise and worth writing down: WITHIN a window
// the filtering is a single correct pass; only the initial state `(x[n−1],
// y[n−1])` is inherited from the END of the previous window rather than from
// the sample before this one, so each window opens with a small transient that
// decays as `Rⁿ` (≈ 255 samples at 20 Hz / 32 kHz).
//
// Two things make that affordable and neither is a claim that it is exact.
// (a) The window function multiplies that leading edge by nearly zero — the
// periodic 4-term Blackman–Harris of `live_singing` has `w[0] = 6e-5`.
// (b) Nothing in this application quotes a level from the live path: ADR 0021
// decision 3 marks every live number *measured, no claim*, and the 0.01 dB
// golden row is measured on the INJECTION path, where a whole file is filtered
// in stream order and this approximation does not exist.
//
// The exact alternatives were considered and both need something the pinned
// protocol does not carry: filtering in the AudioWorklet (which would move a
// convention onto the audio thread, and the `peakAbs` clip latch has to see the
// signal BEFORE the filter in any case), or reconstructing the stream from each
// window's newest `hop_samples` (which needs `hop_samples` in the Worker, and
// `ConfigureMessage` has no such field). Marked `(prov.)`; revisit trigger: a
// measured difference between this path and a stream-filtered reference on the
// same capture, which is a W2 injection-mode experiment.
// ---------------------------------------------------------------------------

import { DcBlocker } from '../dsp/dcblock';
import { smoothPower, spectrumFrame, validateSpectrumConfig, type SpectrumConfig } from '../dsp/pipeline';
import { DENSITY_SCALINGS, toDbfs, toDbfsPerHz, type Scaling } from '../dsp/scale';
import {
  frameTransferables,
  isClipped,
  peakOfLevels,
  type FrameMessage,
  type WorkerRequest,
  type WorkerResponse,
} from './protocol';

/**
 * The Worker global, typed narrowly.
 *
 * `tsconfig.json` carries both `DOM` and `WebWorker` in `lib`, so the ambient
 * `self` is the DOM's `Window`; asserting a Worker type onto it would be a lie
 * a reader has to unpick. Naming exactly the two members this file uses is
 * shorter, honest, and fails at compile time if either is misspelled.
 */
const scope = globalThis as unknown as {
  postMessage(message: WorkerResponse, transfer: ArrayBuffer[]): void;
  addEventListener(type: 'message', listener: (event: MessageEvent<WorkerRequest>) => void): void;
};

/** Everything a configured Worker holds between hops. */
interface State {
  readonly config: SpectrumConfig;
  readonly sampleRateHz: number;
  readonly smoothing: number;
  readonly floorDb: number;
  readonly hold: 'none' | 'peak';
  readonly blocker: DcBlocker | null;
  readonly freqMinHz: number | null;
  readonly freqMaxHz: number | null;
  /** The exponential accumulator, in LINEAR power (ADR 0006 D8). Never handed out. */
  smoothedLinear: Float64Array | null;
  /** The running maximum, in LINEAR power. `null` when `hold` is `none`. */
  holdLinear: Float64Array | null;
}

let state: State | null = null;

function fail(message: string): void {
  scope.postMessage({ type: 'error', message }, []);
}

function configure(request: Extract<WorkerRequest, { type: 'configure' }>): void {
  // Validated HERE as well as in the session: a Worker is a separate program
  // and the message could come from anywhere on the page. `validateSpectrumConfig`
  // is `spectrum.SpectrumConfig.__post_init__` transcribed, so a bad manifest
  // block fails with the same sentence on both sides.
  validateSpectrumConfig(request.config);
  if (!(request.sampleRateHz > 0)) {
    throw new RangeError(`sampleRateHz must be positive, got ${String(request.sampleRateHz)}`);
  }
  if (!(request.smoothing >= 0) || !(request.smoothing < 1)) {
    throw new RangeError(
      `smoothing must be in [0, 1) — the weight of the PREVIOUS frame (ADR 0021 decision 7d) — got ${String(request.smoothing)}`,
    );
  }
  state = {
    config: request.config,
    sampleRateHz: request.sampleRateHz,
    smoothing: request.smoothing,
    floorDb: request.floorDb,
    hold: request.hold,
    blocker: request.dcBlockerHz === null ? null : new DcBlocker(request.dcBlockerHz, request.sampleRateHz),
    freqMinHz: request.freqMinHz ?? null,
    freqMaxHz: request.freqMaxHz ?? null,
    smoothedLinear: null,
    holdLinear: null,
  };
}

/** Drop the accumulators. Called on `reset` — a NEW STREAM, never per frame. */
function reset(): void {
  if (state === null) {
    return;
  }
  state.smoothedLinear = null;
  state.holdLinear = null;
  state.blocker?.reset();
}

function hop(request: Extract<WorkerRequest, { type: 'hop' }>): void {
  const s = state;
  if (s === null) {
    fail('a hop arrived before configure(); the Worker has no window, no rate and no dB reference to use');
    return;
  }

  const frame = spectrumFrame(request.samples, s.config, {
    sampleRateHz: s.sampleRateHz,
    dcBlocker: s.blocker,
    floorDb: s.floorDb,
  });

  // --- smoothing, in LINEAR power (ADR 0006 D8; direction per ADR 0021 7d) ---
  let smoothed = s.smoothedLinear;
  if (smoothed === null || smoothed.length !== frame.linear.length) {
    // The first frame of a stream IS the accumulator: seeding with zeros would
    // make the display climb out of the floor over the first few hops, which
    // reads as a fade-in that the signal did not have.
    smoothed = Float64Array.from(frame.linear);
    s.smoothedLinear = smoothed;
  } else {
    smoothPower(smoothed, frame.linear, s.smoothing);
  }

  // --- hold, also in linear, and on the UNSMOOTHED frame ---------------------
  // A hold is "the loudest this bin has been". Holding the smoothed column
  // would report the loudest the *average* has been, which is lower by however
  // much the smoothing removed — a peak hold that under-reads peaks.
  let holdLinear = s.holdLinear;
  if (s.hold === 'peak') {
    if (holdLinear === null || holdLinear.length !== frame.linear.length) {
      holdLinear = Float64Array.from(frame.linear);
      s.holdLinear = holdLinear;
    } else {
      for (let k = 0; k < holdLinear.length; k += 1) {
        const v = frame.linear[k] as number;
        if (v > (holdLinear[k] as number)) {
          holdLinear[k] = v;
        }
      }
    }
  } else {
    holdLinear = null;
    s.holdLinear = null;
  }

  // --- dB, AFTER the accumulation --------------------------------------------
  const density = DENSITY_SCALINGS.has(s.config.scaling as Scaling);
  const toDb = (linear: Float64Array): Float64Array =>
    density
      ? toDbfsPerHz(linear, s.config.dbfs_reference, s.config.scaling, s.floorDb)
      : toDbfs(linear, s.config.dbfs_reference, s.config.scaling, null, s.floorDb);

  const levelDb = toDb(smoothed);
  const holdDb = holdLinear === null ? null : toDb(holdLinear);

  // The marker tracks the TRACE, so it is read off the smoothed column: a peak
  // label that disagreed with the line under it would be two answers on one
  // readout. The estimator is `protocol.ts`'s, which is `peak.py`'s.
  const peak = peakOfLevels(levelDb, s.sampleRateHz, s.config.fft_size, s.freqMinHz, s.freqMaxHz);

  const message: FrameMessage = {
    type: 'frame',
    frameIndex: request.frameIndex,
    frequencyHz: frame.frequencyHz,
    levelDb,
    rawLevelDb: frame.levelDb,
    holdDb,
    peak,
    clipped: isClipped(request.peakAbs),
    peakAbs: request.peakAbs,
    capturedAtMs: request.capturedAtMs,
    computedAtMs: performance.now(),
    levelUnit: frame.levelUnit,
    enbwHz: frame.enbwHz,
  };
  scope.postMessage(message, frameTransferables(message));
}

scope.addEventListener('message', (event: MessageEvent<WorkerRequest>) => {
  const request = event.data;
  try {
    switch (request.type) {
      case 'configure':
        configure(request);
        return;
      case 'reset':
        reset();
        return;
      case 'hop':
        hop(request);
        return;
      default:
        // `request` is `never` here; the cast is what lets the message say what
        // actually arrived instead of "undefined".
        fail(`unknown request ${JSON.stringify((request as { type?: unknown }).type)}`);
        return;
    }
  } catch (error) {
    // A throw inside a Worker is an `error` event on the main thread with no
    // useful message in several browsers. Sending it as a typed message is what
    // puts it on SCREEN, which is the same rule the rate refusal follows.
    fail(error instanceof Error ? `${error.name}: ${error.message}` : String(error));
  }
});
