//
// The one spectrum function — decode → (optional DC block) → window → FFT →
// one-sided power → scale → dB.
//
// BOTH CALLERS CALL THIS. The golden oracle suite and the live Worker run the
// same `spectrumFrame`, so the thing measured against
// `host/golden/outputs/tier0-synthetic` at W1 is literally the thing the
// AudioWorklet feeds at 50 Hz. Two entry points with "the same" arithmetic
// would drift the first time one of them was optimised; ADR 0021 decision 7(c)
// says "*the same Tier-0 files against the same goldens* is literally true",
// and this is the file where that becomes true.
//
// `SpectrumConfig` carries the schema's SNAKE_CASE key names on purpose: the
// object handed to `spectrumFrame` IS a manifest's `analyses.spectrum` block,
// parsed and passed through untouched. A camelCase mirror would need a
// translation layer, and translation layers are where golden files quietly stop
// meaning what they say (`spectrum.py`'s own opening comment).
// ----------------------------------------------------------------------------

import { DcBlocker } from './dcblock';
import { RealFft, allocSpectrum } from './fft';
import {
  DBFS_REFERENCES,
  DEFAULT_FLOOR_DB,
  DEFAULT_INT16_SCALE,
  DENSITY_SCALINGS,
  DTYPES,
  INT16_SCALES,
  NORMALIZATIONS,
  SCALINGS,
  binFrequencies,
  oneSidedPower,
  scale,
  toDbfs,
  toDbfsPerHz,
  type Scaling,
} from './scale';
import { WINDOW_FAMILIES, enbwHz, windowSums, windowTable, type WindowSums } from './window';

/**
 * The `analyses.spectrum` block of a golden manifest — exactly its nine keys,
 * in schema order (`host/golden/manifest.schema.yaml`).
 *
 * Every field is required by the schema (ADR 0009 item 1(a): an unstated
 * convention is not a value), so there are no defaults here and none may be
 * added: a key this application filled in silently would be a convention the
 * manifest does not record.
 */
export interface SpectrumConfig {
  readonly window: string;
  readonly window_length_samples: number;
  readonly fftbins: boolean;
  readonly fft_size: number;
  readonly normalization: string;
  readonly scaling: string;
  readonly dbfs_reference: string;
  readonly int16_scale: number;
  readonly dtype: string;
}

/** The nine keys, in schema order — a test asserts a config carries these and nothing else. */
export const SPECTRUM_CONFIG_KEYS: readonly (keyof SpectrumConfig)[] = Object.freeze([
  'window',
  'window_length_samples',
  'fftbins',
  'fft_size',
  'normalization',
  'scaling',
  'dbfs_reference',
  'int16_scale',
  'dtype',
]);

/**
 * The convention ADR 0006 ratifies, as the worked example of
 * `manifest.schema.yaml` writes it — the one every Tier-0 spectrum reference
 * uses unless a set says otherwise. Mirrors `spectrum.ADR_0006_DEFAULT`.
 */
export const ADR_0006_DEFAULT: SpectrumConfig = Object.freeze({
  window: 'hann',
  window_length_samples: 4096,
  fftbins: true,
  fft_size: 4096,
  normalization: 'S1',
  scaling: 'power_spectrum',
  dbfs_reference: 'sine',
  int16_scale: DEFAULT_INT16_SCALE,
  dtype: 'float64',
});

/** `spectrum.SpectrumConfig.__post_init__`, transcribed check for check. */
export function validateSpectrumConfig(cfg: SpectrumConfig): void {
  if (!(cfg.window in WINDOW_FAMILIES)) {
    throw new RangeError(`window must be a §4.3 family or 'rect', got ${JSON.stringify(cfg.window)}`);
  }
  if (!Number.isInteger(cfg.window_length_samples) || cfg.window_length_samples < 2) {
    throw new RangeError(
      `window length must be an integer >= 2 (manifest schema), got ${String(cfg.window_length_samples)}`,
    );
  }
  if (typeof cfg.fftbins !== 'boolean') {
    throw new RangeError('fftbins must be a bool');
  }
  if (!Number.isInteger(cfg.fft_size) || cfg.fft_size < 2) {
    throw new RangeError(`fft_size must be an integer >= 2, got ${String(cfg.fft_size)}`);
  }
  if (cfg.fft_size < cfg.window_length_samples) {
    throw new RangeError('fft_size < window_length_samples would truncate the window; only zero-padding is defined');
  }
  if (cfg.fft_size % 2 !== 0) {
    throw new RangeError('fft_size must be even: the DC/Nyquist rule of ADR 0006 D2 is stated for an even transform');
  }
  if (!(NORMALIZATIONS as readonly string[]).includes(cfg.normalization)) {
    throw new RangeError(`normalization must be one of ${NORMALIZATIONS.join(', ')}, got ${JSON.stringify(cfg.normalization)}`);
  }
  if (!(SCALINGS as readonly string[]).includes(cfg.scaling)) {
    throw new RangeError(`scaling must be one of ${SCALINGS.join(', ')}, got ${JSON.stringify(cfg.scaling)}`);
  }
  if (!(DBFS_REFERENCES as readonly string[]).includes(cfg.dbfs_reference)) {
    throw new RangeError(`dbfs_reference must be one of ${DBFS_REFERENCES.join(', ')}, got ${JSON.stringify(cfg.dbfs_reference)}`);
  }
  if (!(INT16_SCALES as readonly number[]).includes(cfg.int16_scale)) {
    throw new RangeError(`int16_scale must be one of ${INT16_SCALES.join(', ')}, got ${String(cfg.int16_scale)}`);
  }
  if (!(DTYPES as readonly string[]).includes(cfg.dtype)) {
    throw new RangeError(`dtype must be one of ${DTYPES.join(', ')}, got ${JSON.stringify(cfg.dtype)}`);
  }
}

/**
 * int16 PCM → float in [−1, 1): `x / int16_scale`, applied EXACTLY ONCE
 * (ADR 0003 d.2, ADR 0006 D3).
 *
 * Refuses anything that is not an `Int16Array`, for the reason
 * `spectrum.int16_to_float` gives: a float array scaled a second time reads
 * −90.3 dB low, which is the kind of error that looks like a microphone problem.
 */
export function int16ToFloat(x: Int16Array, int16Scale: number = DEFAULT_INT16_SCALE): Float64Array {
  if (!(x instanceof Int16Array)) {
    throw new TypeError('int16ToFloat expects Int16Array samples (the 1/32768 seam is applied exactly once)');
  }
  if (!(INT16_SCALES as readonly number[]).includes(int16Scale)) {
    throw new RangeError(`int16_scale must be one of ${INT16_SCALES.join(', ')}, got ${String(int16Scale)}`);
  }
  const out = new Float64Array(x.length);
  for (let i = 0; i < x.length; i += 1) {
    out[i] = (x[i] as number) / int16Scale;
  }
  return out;
}

/** What `spectrumFrame` needs that the manifest block does not carry. */
export interface SpectrumFrameOptions {
  /** Sample rate in Hz. From the manifest's `inputs[].sample_rate`, or the AudioContext's asserted rate. */
  readonly sampleRateHz: number;
  /**
   * ADR 0006 D7's blocker, or `null`/absent for OFF.
   *
   * OFF is what the oracle comparison uses, and the manifest says so in words:
   * "spectrum = the first device frame, samples [0, N) of the int16 file scaled
   * by 1/32768, BEFORE the DC blocker". The live path passes a blocker and
   * keeps it across hops.
   */
  readonly dcBlocker?: DcBlocker | null;
  /** dB floor; ADR 0006 D3's −200 unless a caller states otherwise. */
  readonly floorDb?: number;
}

/** One frame's answer: the levels, the axis they sit on, and the window constants behind them. */
export interface SpectrumFrame {
  /** Bin centre frequencies `k·fs/N`, `N/2+1` of them. */
  readonly frequencyHz: Float64Array;
  /** The level column: dBFS, or dBFS/Hz for a density scaling. `levelUnit` says which. */
  readonly levelDb: Float64Array;
  /** `'dBFS'` or `'dBFS/Hz'` — ADR 0006 D3: two axes, never mixed on one readout. */
  readonly levelUnit: 'dBFS' | 'dBFS/Hz';
  /**
   * The LINEAR values `cfg.scaling` names, before the dB stage.
   *
   * Exposed because ADR 0006 D8 requires smoothing, averaging and hold to
   * happen HERE and never in dB: the log-domain mean of a noise bin is 2.507 dB
   * low. A display that smoothed `levelDb` would be wrong by that much and
   * would look plausible.
   */
  readonly linear: Float64Array;
  readonly s1: number;
  readonly s2: number;
  readonly nenbw: number;
  readonly enbwHz: number;
}

interface Plan {
  readonly table: Float32Array;
  readonly sums: WindowSums;
  readonly fft: RealFft;
  readonly spectrum: Float64Array;
  readonly windowed: Float64Array;
  readonly power: Float64Array;
}

const PLANS = new Map<string, Plan>();

function planFor(cfg: SpectrumConfig): Plan {
  const key = `${cfg.window}|${String(cfg.window_length_samples)}|${String(cfg.fft_size)}`;
  const cached = PLANS.get(key);
  if (cached !== undefined) {
    return cached;
  }
  const table = windowTable(cfg.window, cfg.window_length_samples);
  const plan: Plan = {
    table,
    sums: windowSums(table),
    fft: new RealFft(cfg.fft_size),
    spectrum: allocSpectrum(cfg.fft_size),
    windowed: new Float64Array(cfg.window_length_samples),
    power: new Float64Array(cfg.fft_size / 2 + 1),
  };
  PLANS.set(key, plan);
  return plan;
}

/** Drop every cached window table and FFT plan. Tests use it; the live path never needs it. */
export function clearPlanCache(): void {
  PLANS.clear();
}

/**
 * One frame of the ADR 0006 pipeline.
 *
 * `samples` is either the file's own `Int16Array` — decoded here by the
 * `1/int16_scale` seam, exactly once — or a float array already in [−1, 1) as
 * an AudioWorklet delivers it, which is NOT scaled again. The dispatch is on
 * the array type and is the only place in this application that decides it.
 *
 * Only the first `window_length_samples` samples are read: this is the FIRST
 * DEVICE FRAME, from sample 0 (golden-files.md's frame-grid trap — the device
 * frames from sample 0 with a hop; Praat and librosa do not). Fewer samples
 * than that is an error, not a zero-pad, because a golden file of a padded
 * frame would pin a different signal than its input sha256 names.
 */
export function spectrumFrame(
  samples: Int16Array | Float32Array | Float64Array,
  cfg: SpectrumConfig,
  options: SpectrumFrameOptions,
): SpectrumFrame {
  validateSpectrumConfig(cfg);
  if (!cfg.fftbins) {
    throw new RangeError(
      "fftbins=false asks for a symmetric window; ADR 0006 D1 rejects that form outright " +
        '(NENBW no longer equals the closed form) and this module does not build it',
    );
  }
  if (cfg.dtype !== 'float64') {
    throw new RangeError(
      `dtype ${JSON.stringify(cfg.dtype)}: this module computes in IEEE double throughout (ADR 0021 decision 2), ` +
        'so it cannot reproduce a float32 set — that set needs the device lane, not the browser instrument',
    );
  }
  const { sampleRateHz } = options;
  if (!(sampleRateHz > 0)) {
    throw new RangeError(`sampleRateHz must be positive, got ${String(sampleRateHz)}`);
  }
  const n = cfg.window_length_samples;
  if (samples.length < n) {
    throw new RangeError(
      `need at least window_length_samples = ${String(n)} samples, got ${String(samples.length)}`,
    );
  }

  const plan = planFor(cfg);
  const floorDb = options.floorDb ?? DEFAULT_FLOOR_DB;

  // --- decode: the 1/int16_scale seam, applied exactly once ------------------
  const frame = new Float64Array(n);
  if (samples instanceof Int16Array) {
    const s = cfg.int16_scale;
    for (let j = 0; j < n; j += 1) {
      frame[j] = (samples[j] as number) / s;
    }
  } else {
    for (let j = 0; j < n; j += 1) {
      frame[j] = samples[j] as number;
    }
  }

  // --- optional DC block, BEFORE the window and AFTER the scaling (D7) -------
  const blocker = options.dcBlocker;
  if (blocker !== undefined && blocker !== null) {
    blocker.process(frame, frame);
  }

  // --- window ---------------------------------------------------------------
  const { table, sums, fft, spectrum, windowed, power } = plan;
  for (let j = 0; j < n; j += 1) {
    windowed[j] = (frame[j] as number) * (table[j] as number);
  }

  // --- transform (unnormalised), one-sided power, scale ----------------------
  fft.forward(windowed, spectrum);
  oneSidedPower(spectrum, power);
  const linear = scale(power, sums.s1, sums.s2, sampleRateHz, cfg.normalization, cfg.scaling);

  // --- dB -------------------------------------------------------------------
  const scaling = cfg.scaling as Scaling;
  const density = DENSITY_SCALINGS.has(scaling);
  const levelDb = density
    ? toDbfsPerHz(linear, cfg.dbfs_reference, cfg.scaling, floorDb)
    : toDbfs(linear, cfg.dbfs_reference, cfg.scaling, null, floorDb);

  return {
    frequencyHz: binFrequencies(sampleRateHz, cfg.fft_size),
    levelDb,
    levelUnit: density ? 'dBFS/Hz' : 'dBFS',
    linear,
    s1: sums.s1,
    s2: sums.s2,
    nenbw: sums.nenbw,
    enbwHz: enbwHz(sums.nenbw, sampleRateHz, cfg.fft_size),
  };
}

/**
 * Exponential smoothing across frames, in LINEAR power — ADR 0006 D8 and
 * ADR 0021 decision 7(d).
 *
 *     P̂[k] ← s·P̂[k] + (1 − s)·P[k]
 *
 * `s` is the weight of the PREVIOUS frame, so a LARGER value is smoother —
 * Spectroid's sense, and the reading every consumer of `analysis.smoothing`
 * must share. `(prov.)` until it is written into `preset-schema.md` §4, which
 * says only "exponential coefficient" today; ADR 0021 decision 7(d) records
 * that three implementations were about to guess.
 *
 * Never in dB: the log-domain mean of a noise-like bin is `−γ·10/ln 10` =
 * −2.507 dB (Heinzel §10 for the rule, the figure derived in ADR 0006 D8).
 */
export function smoothPower(previous: Float64Array, current: Float64Array, s: number): Float64Array {
  if (!(s >= 0) || !(s < 1)) {
    throw new RangeError(`smoothing must be in [0, 1) — the weight of the PREVIOUS frame — got ${String(s)}`);
  }
  if (previous.length !== current.length) {
    throw new RangeError('smoothing needs both frames on the same bin grid');
  }
  for (let k = 0; k < previous.length; k += 1) {
    previous[k] = s * (previous[k] as number) + (1 - s) * (current[k] as number);
  }
  return previous;
}
