//
// The Worker's message contract, and the peak estimator that rides on it.
//
// PURE, AND UNIT-TESTED IN NODE. Nothing here touches a Worker, an
// AudioContext or a canvas. The Worker imports it, the session imports it, and
// `tests/unit/` imports it — so the estimator that produces the number on
// screen is literally the estimator the ≤ 3 cents row is measured on, not a
// second one written to be testable.
//
// THE PEAK ESTIMATOR IS A TRANSCRIPTION, NOT A DESIGN.
// `host/src/spectral_host/capture/peak.py` — behind `spectral-web peak`, the
// founding document's M0 — already owns this arithmetic, and ADR 0021 decision
// 2's whole point is that implementations are compared to the oracle rather
// than each other. A second interpolator here would be a second convention to
// keep in step, so `interpolatePeak` and `searchBounds` below are that module's
// `interpolate_peak` and `_search_bounds` line for line, including the two
// refusals that look like edge cases and are not:
//
//   * a non-downward parabola (`denominator >= 0`) returns the bin unchanged —
//     a flat or rising triple is not a peak, and extrapolating from one moves
//     the answer AWAY from the data;
//   * `|d| > 1` returns the bin unchanged — an offset of more than a whole bin
//     means the three levels do not describe a single lobe.
//
// And the search band is `1 … N/2−1` before any display limit is applied: DC
// and Nyquist have no two neighbours to fit through, and DC is where an
// uncorrected offset lives, so "the peak" of a signal with a DC offset would
// be a fact about the ADC rather than about the note being sung.
//
// MEASURED THROUGH THIS FILE (tests/unit/the-peak-estimator-reproduces-the-python-readings.test.ts):
// `sine_440_m20dBFS_32k` +0.48 cents and `sine_1000_m20dBFS_32k` +0.00 cents,
// the same two figures the roadmap records for `spectral-web peak` at W0
// (commit 5867e2a). The tolerance is read from `docs/validation/golden-files.md`.
// ----------------------------------------------------------------------------

import type { SpectrumConfig } from '../dsp/pipeline';

/* --- requests: main thread → Worker ---------------------------------------- */

/**
 * Everything the Worker needs before it may compute a frame.
 *
 * `smoothing` is the weight of the PREVIOUS frame (ADR 0021 decision 7(d)), so
 * a larger value is smoother; `dcBlockerHz` is ADR 0006 D7's corner, or `null`
 * for off; `floorDb` is D3's floor.
 *
 * `freqMinHz` / `freqMaxHz` are the preset's `display.freq_min_hz` and
 * `display.freq_max_hz`, and they are the ONE addition this file makes to the
 * message shape the W1 contract pinned. The reason is that the same contract
 * requires the peak search to be "restricted to `display.freq_min_hz …
 * freq_max_hz`" while the pinned six fields carry no band — so either the band
 * arrives here or the restriction does not happen. They are OPTIONAL: a
 * `configure` without them searches `peak.py`'s own default range (every
 * interpolable bin), which is what `spectral-web peak` does without
 * `--min-hz` / `--max-hz`.
 */
export interface ConfigureMessage {
  readonly type: 'configure';
  readonly config: SpectrumConfig;
  readonly sampleRateHz: number;
  readonly smoothing: number;
  readonly dcBlockerHz: number | null;
  readonly floorDb: number;
  readonly hold: 'none' | 'peak';
  readonly freqMinHz?: number;
  readonly freqMaxHz?: number;
}

/** One hop of capture, relayed from the AudioWorklet. `samples` arrives TRANSFERRED. */
export interface HopMessage {
  readonly type: 'hop';
  readonly samples: Float32Array;
  readonly frameIndex: number;
  readonly capturedAtMs: number;
  readonly peakAbs: number;
}

/** Drop the smoothing state, the hold and the DC blocker's state. Sent on a STREAM change. */
export interface ResetMessage {
  readonly type: 'reset';
}

export type WorkerRequest = ConfigureMessage | HopMessage | ResetMessage;

/* --- responses: Worker → main thread --------------------------------------- */

/** The interpolated peak of one frame. */
export interface PeakReading {
  /** Interpolated peak frequency, Hz: `(k + d)·fs/N`. */
  readonly hz: number;
  /** Interpolated level at that frequency, in the frame's own unit. */
  readonly db: number;
  /** The bin `argmax` chose, before interpolation. */
  readonly bin: number;
  /** Sub-bin offset `d`; `|d| ≤ 1` by construction, and 0 when the fit was refused. */
  readonly deltaBins: number;
}

/**
 * One computed frame. Every array is a FRESH allocation, so every one of them
 * may be transferred (`frameTransferables`) without costing the Worker its
 * state — the smoothing accumulator and the hold are kept in linear power and
 * are never handed out.
 */
export interface FrameMessage {
  readonly type: 'frame';
  readonly frameIndex: number;
  readonly frequencyHz: Float64Array;
  /** The display column: SMOOTHED (ADR 0006 D8: the smoothing happened in linear power). */
  readonly levelDb: Float64Array;
  /** The same frame, UNSMOOTHED. Both are sent because a residual measured against the oracle is a
      statement about one frame, and a smoothed column is a statement about several. */
  readonly rawLevelDb: Float64Array;
  /** Peak hold, or `null` when the preset asks for `hold: none`. */
  readonly holdDb: Float64Array | null;
  readonly peak: PeakReading;
  /** This hop reached the clip threshold. LATCHING is the session's job, not the Worker's. */
  readonly clipped: boolean;
  readonly peakAbs: number;
  /** The AudioContext clock, ms (see `pcm-hop.worklet.ts`). */
  readonly capturedAtMs: number;
  /** The Worker's `performance.now()`, ms. A DIFFERENT TIME ORIGIN from `capturedAtMs`: the two may
      never be subtracted, and no latency figure comes out of this pair (ADR 0021 decision 3). */
  readonly computedAtMs: number;
  readonly levelUnit: 'dBFS' | 'dBFS/Hz';
  readonly enbwHz: number;
}

/** A refusal, carried as a message rather than thrown: a Worker exception is a line in a console nobody has open. */
export interface ErrorMessage {
  readonly type: 'error';
  readonly message: string;
}

export type WorkerResponse = FrameMessage | ErrorMessage;

/**
 * The buffers of a frame, for the `transfer` argument of `postMessage`.
 *
 * Every array in a `FrameMessage` is freshly allocated by the Worker, so
 * transferring them is free of aliasing risk — and structured-cloning four
 * arrays of `N/2+1` doubles fifty times a second is not.
 */
export function frameTransferables(frame: FrameMessage): ArrayBuffer[] {
  const buffers: ArrayBuffer[] = [
    frame.frequencyHz.buffer as ArrayBuffer,
    frame.levelDb.buffer as ArrayBuffer,
    frame.rawLevelDb.buffer as ArrayBuffer,
  ];
  if (frame.holdDb !== null) {
    buffers.push(frame.holdDb.buffer as ArrayBuffer);
  }
  return buffers;
}

/* --- clipping --------------------------------------------------------------- */

/**
 * The clip latch's threshold on `|x|` of the RAW capture.
 *
 * **A DISAGREEMENT WORTH SEEING RATHER THAN AVERAGING.** ADR 0021 decision 1
 * writes the founding document's flag as `|s| ≥ 0.99` FS; the W1 contract
 * writes it as `|x| >= 1.0`. They differ by 0.087 dB and they answer different
 * questions — 1.0 is *this sample is at the rail*, 0.99 is *this take is about
 * to be at the rail*. W1 implements the contract's 1.0, in ONE constant, so
 * that reconciling them later is one edit and a note in the record rather than
 * a hunt through three files. Flagged for W2, where the readout strip that
 * shows it is built.
 */
export const CLIP_THRESHOLD = 1.0;

/** Did this hop clip? One expression, used by the Worker and by any test of it. */
export function isClipped(peakAbs: number): boolean {
  return peakAbs >= CLIP_THRESHOLD;
}

/* --- the peak estimator, transcribed from peak.py --------------------------- */

/**
 * Parabolic interpolation on the dB values around bin `k`.
 *
 *     d = 0.5·(a − g)/(a − 2b + g),   ŷ = b − 0.25·(a − g)·d
 *
 * with `a, b, g` the levels at `k−1, k, k+1`. **In dB, not in linear power**:
 * a Gaussian window's log-magnitude main lobe IS a parabola, and for the
 * cosine-sum families of ADR 0006 D1 the dB fit is the better approximation of
 * the two — the same choice `peak.py` makes, and the reason both are held to
 * one row of `docs/validation/golden-files.md`.
 *
 * Returns `{deltaBins: 0, levelDb: levels[k]}` unchanged at an edge bin, on a
 * non-downward parabola, and on `|d| > 1`. See the header for why each of the
 * three is a refusal rather than a best effort.
 */
export function interpolatePeak(
  levelsDb: ArrayLike<number>,
  k: number,
): { readonly deltaBins: number; readonly levelDb: number } {
  if (!Number.isInteger(k) || k < 0 || k >= levelsDb.length) {
    throw new RangeError(`bin ${String(k)} is outside the ${String(levelsDb.length)} levels given`);
  }
  const b = levelsDb[k] as number;
  if (k === 0 || k === levelsDb.length - 1) {
    return { deltaBins: 0, levelDb: b };
  }
  const a = levelsDb[k - 1] as number;
  const g = levelsDb[k + 1] as number;
  const denominator = a - 2 * b + g;
  if (denominator >= 0 || !Number.isFinite(denominator)) {
    return { deltaBins: 0, levelDb: b };
  }
  const d = (0.5 * (a - g)) / denominator;
  if (!Number.isFinite(d) || Math.abs(d) > 1) {
    return { deltaBins: 0, levelDb: b };
  }
  return { deltaBins: d, levelDb: b - 0.25 * (a - g) * d };
}

/**
 * Inclusive bin range to search, always inside `1 … N/2−1` so that
 * interpolation has both neighbours. `peak.py`'s `_search_bounds`.
 */
export function searchBounds(
  fs: number,
  fftSize: number,
  minHz?: number | null,
  maxHz?: number | null,
): { readonly lo: number; readonly hi: number } {
  if (!(fs > 0)) {
    throw new RangeError(`fs must be positive, got ${String(fs)}`);
  }
  if (!Number.isInteger(fftSize) || fftSize < 4 || fftSize % 2 !== 0) {
    throw new RangeError(`fft size must be an even integer >= 4, got ${String(fftSize)}`);
  }
  const bins = fftSize / 2 + 1;
  let lo = 1;
  let hi = bins - 2;
  const binWidth = fs / fftSize;
  if (minHz !== undefined && minHz !== null) {
    lo = Math.max(lo, Math.ceil(minHz / binWidth));
  }
  if (maxHz !== undefined && maxHz !== null) {
    hi = Math.min(hi, Math.floor(maxHz / binWidth));
  }
  if (lo > hi) {
    throw new RangeError(
      `search band [${String(minHz)}, ${String(maxHz)}] Hz holds no interpolable bin at fs = ${String(fs)}, ` +
        `N = ${String(fftSize)} (bin width ${String(binWidth)} Hz)`,
    );
  }
  return { lo, hi };
}

/**
 * The interpolated peak of one level column — `peak.py`'s `peak_of_frame`,
 * minus the part that computes the spectrum (which is `dsp/pipeline.ts`'s job
 * on both sides of this application).
 *
 * `argmax` takes the FIRST maximum, as `np.argmax` does, so a two-tone frame
 * with two exactly equal bins gives the lower frequency on both sides.
 */
export function peakOfLevels(
  levelsDb: ArrayLike<number>,
  fs: number,
  fftSize: number,
  minHz?: number | null,
  maxHz?: number | null,
): PeakReading {
  const bins = fftSize / 2 + 1;
  if (levelsDb.length !== bins) {
    throw new RangeError(
      `a one-sided spectrum of N = ${String(fftSize)} has ${String(bins)} bins, got ${String(levelsDb.length)}`,
    );
  }
  const { lo, hi } = searchBounds(fs, fftSize, minHz, maxHz);
  let k = lo;
  let best = levelsDb[lo] as number;
  for (let i = lo + 1; i <= hi; i += 1) {
    const v = levelsDb[i] as number;
    if (v > best) {
      best = v;
      k = i;
    }
  }
  const { deltaBins, levelDb } = interpolatePeak(levelsDb, k);
  return { hz: ((k + deltaBins) * fs) / fftSize, db: levelDb, bin: k, deltaBins };
}
