//
// The real FFT — a radix-2 complex transform of size N/2 plus the real-packing
// split step, which is the structure ADR 0006 D5 chose for the watch.
//
// WHY THIS STRUCTURE AND NOT A LIBRARY. ADR 0021 decision 2 does not mandate a
// kernel ("a hand-written radix-2 complex-N/2 plus the real-packing split ... or
// an MIT kernel; whichever is used passes the rows or it does not ship"), so the
// choice is free — and building the same shape the firmware builds makes this
// module a second witness to the SAME arithmetic the device performs, not just
// to the same answer. It also keeps `host/web/package.json` at zero runtime
// dependencies, which is a property worth more than the ~120 lines below.
//
// WHY float64 SCRATCH. JavaScript arithmetic is IEEE double; storing an
// intermediate in a Float32Array would add one rounding per element per stage
// and buy nothing — there is no float32 register file underneath to be faster.
// The device pays float32 because its FPU is single-precision; that difference
// is what the tolerance table absorbs (golden-files.md, "float32 accumulation
// across 11 radix-2 stages"), and reproducing the device's rounding here would
// destroy the independence ADR 0021 decision 2 is buying.
//
// THE TRANSFORM IS UNNORMALISED — no 1/N, no 1/√N (ADR 0006 D2). Scaling is
// `scale.ts`'s job, exactly as it is `spectral_core`'s job on the device.
// ----------------------------------------------------------------------------

/** Smallest transform this class builds. `n = 8` → a complex-4 kernel, the smallest with a real split step. */
export const MIN_FFT_SIZE = 8;

/**
 * Largest transform this class builds.
 *
 * 16384 is `2 × 8192`, one power of two above the largest preset FFT
 * (`room_noise_floor`, `sustained_pitch_lab` and `vowel_formant_study` ask for
 * 8192), so a zero-padded 8192-sample frame still fits.
 */
export const MAX_FFT_SIZE = 16384;

function isPowerOfTwo(n: number): boolean {
  return Number.isInteger(n) && n > 0 && (n & (n - 1)) === 0;
}

/**
 * A planned real-input FFT of a fixed size.
 *
 * Twiddles and the bit-reversal permutation are built once in the constructor
 * and reused for every frame — the live path runs this 50 times a second and a
 * per-frame `Math.cos` sweep would dominate it.
 */
export class RealFft {
  /** Transform length in real samples. */
  readonly n: number;

  /** Length of the complex transform underneath: `n / 2` (ADR 0006 D5). */
  readonly nc: number;

  /** `cos(−2πt/nc)` for `t = 0 … nc/2 − 1`: the complex kernel's twiddles. */
  private readonly cosC: Float64Array;

  /** `sin(−2πt/nc)` for `t = 0 … nc/2 − 1`. */
  private readonly sinC: Float64Array;

  /** `cos(2πk/n)` for `k = 0 … nc/2` — the half-bin angles of ADR 0006 D5's split step. */
  private readonly cosSplit: Float64Array;

  /** `sin(2πk/n)` for `k = 0 … nc/2`. */
  private readonly sinSplit: Float64Array;

  /** Bit-reversal permutation of length `nc`. */
  private readonly rev: Uint32Array;

  /** Interleaved re/im scratch of length `2·nc`, reused across frames. */
  private readonly z: Float64Array;

  constructor(n: number) {
    if (!isPowerOfTwo(n) || n < MIN_FFT_SIZE || n > MAX_FFT_SIZE) {
      throw new RangeError(
        `fft size must be a power of two in [${String(MIN_FFT_SIZE)}, ${String(MAX_FFT_SIZE)}], got ${String(n)}`,
      );
    }
    this.n = n;
    this.nc = n / 2;

    const half = this.nc / 2;
    this.cosC = new Float64Array(Math.max(half, 1));
    this.sinC = new Float64Array(Math.max(half, 1));
    for (let t = 0; t < half; t += 1) {
      const angle = (-2 * Math.PI * t) / this.nc;
      this.cosC[t] = Math.cos(angle);
      this.sinC[t] = Math.sin(angle);
    }

    // ADR 0006 D5: "half-bin angles cos/sin(πk/N_c) for k = 0 … N_c/2" — and
    // πk/N_c is 2πk/n, the split step's own angle. Storing only k ≤ nc/2 is
    // what makes the table `4·(N_c+2)` bytes on the device rather than twice
    // that: the loop below handles k and nc−k from the same entry.
    this.cosSplit = new Float64Array(half + 1);
    this.sinSplit = new Float64Array(half + 1);
    for (let k = 0; k <= half; k += 1) {
      const angle = (2 * Math.PI * k) / n;
      this.cosSplit[k] = Math.cos(angle);
      this.sinSplit[k] = Math.sin(angle);
    }

    this.rev = new Uint32Array(this.nc);
    const bits = Math.log2(this.nc);
    for (let i = 0; i < this.nc; i += 1) {
      let r = 0;
      for (let b = 0; b < bits; b += 1) {
        r = (r << 1) | ((i >>> b) & 1);
      }
      this.rev[i] = r;
    }

    this.z = new Float64Array(2 * this.nc);
  }

  /** Number of one-sided bins the transform produces: `n/2 + 1`, DC through Nyquist inclusive. */
  get bins(): number {
    return this.nc + 1;
  }

  /**
   * Forward transform of `n` real samples, UNNORMALISED.
   *
   * `out` receives `2·(n/2+1)` interleaved re/im values — `out[2k]` is
   * `Re X[k]`, `out[2k+1]` is `Im X[k]`, for `k = 0 … n/2`. DC and Nyquist have
   * zero imaginary part by construction and are written as such; nothing
   * downstream may assume they are absent, because the packing conventions that
   * fold Nyquist into `Im X[0]` are exactly the ones that produce a 3 dB error
   * at two bins (ADR 0006 D2's divergence from Heinzel's waiver).
   *
   * `samples` shorter than `n` is ZERO-PADDED — `fft_size > window_length_samples`
   * is the schema's only defined use of the two fields differing. Longer is
   * refused: truncation is not a convention of ADR 0006.
   */
  forward(samples: Float64Array | Float32Array, out: Float64Array): Float64Array {
    if (samples.length > this.n) {
      throw new RangeError(
        `frame of ${String(samples.length)} samples exceeds the transform size ${String(this.n)}: ` +
          'truncation is not a convention of ADR 0006',
      );
    }
    if (out.length < 2 * this.bins) {
      throw new RangeError(
        `out needs ${String(2 * this.bins)} slots (2 × (n/2+1) interleaved re/im), got ${String(out.length)}`,
      );
    }

    const { nc, z, rev } = this;

    // Pack the real sequence as nc complex points, bit-reversed on the way in:
    // z[j] = x[2j] + i·x[2j+1]. Samples past the end of `samples` are zero,
    // which is the zero-pad.
    for (let j = 0; j < nc; j += 1) {
      const r = rev[j] as number;
      const evenIndex = 2 * j;
      const oddIndex = evenIndex + 1;
      z[2 * r] = evenIndex < samples.length ? (samples[evenIndex] as number) : 0;
      z[2 * r + 1] = oddIndex < samples.length ? (samples[oddIndex] as number) : 0;
    }

    // Decimation-in-time radix-2 Cooley–Tukey over the nc complex points.
    for (let len = 2; len <= nc; len <<= 1) {
      const halfLen = len >> 1;
      const stride = nc / len;
      for (let base = 0; base < nc; base += len) {
        for (let j = 0, t = 0; j < halfLen; j += 1, t += stride) {
          const wr = this.cosC[t] as number;
          const wi = this.sinC[t] as number;
          const iu = 2 * (base + j);
          const iv = 2 * (base + j + halfLen);
          const vr = z[iv] as number;
          const vi = z[iv + 1] as number;
          const tr = vr * wr - vi * wi;
          const ti = vr * wi + vi * wr;
          const ur = z[iu] as number;
          const ui = z[iu + 1] as number;
          z[iu] = ur + tr;
          z[iu + 1] = ui + ti;
          z[iv] = ur - tr;
          z[iv + 1] = ui - ti;
        }
      }
    }

    // The split step (ADR 0006 D5; the packing identity of bibliography 04 #1,
    // Smith SASP). With Fe[k] = ½(Z[k] + conj(Z[nc−k])) the DFT of the even
    // samples and Fo[k] = −½i(Z[k] − conj(Z[nc−k])) that of the odd ones,
    //     X[k]      = Fe[k] + W^k·Fo[k],
    //     X[nc−k]   = conj(Fe[k] − W^k·Fo[k]),   W = e^{−2πi/n}
    // so one table entry serves two output bins and the loop runs to nc/2.
    const z0r = z[0] as number;
    const z0i = z[1] as number;
    out[0] = z0r + z0i; // X[0] — real, and NOT doubled anywhere downstream
    out[1] = 0;
    out[2 * nc] = z0r - z0i; // X[n/2], the Nyquist bin — also real
    out[2 * nc + 1] = 0;

    for (let k = 1; k <= nc >> 1; k += 1) {
      const ar = z[2 * k] as number;
      const ai = z[2 * k + 1] as number;
      const br = z[2 * (nc - k)] as number;
      const bi = z[2 * (nc - k) + 1] as number;

      const feR = 0.5 * (ar + br);
      const feI = 0.5 * (ai - bi);
      const foR = 0.5 * (ai + bi);
      const foI = -0.5 * (ar - br);

      const c = this.cosSplit[k] as number;
      const s = this.sinSplit[k] as number;
      // W^k = cos θ − i sin θ with θ = 2πk/n.
      const bR = foR * c + foI * s;
      const bI = foI * c - foR * s;

      out[2 * k] = feR + bR;
      out[2 * k + 1] = feI + bI;
      out[2 * (nc - k)] = feR - bR;
      out[2 * (nc - k) + 1] = bI - feI;
    }

    return out;
  }
}

/** Allocate the output buffer a `RealFft` of size `n` writes into. */
export function allocSpectrum(n: number): Float64Array {
  return new Float64Array(2 * (n / 2 + 1));
}
